package com.yigongbao.backup.job;

import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.dao.DuplicateKeyException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

/** 基于条件更新、租约和 fencing token 的多实例持久化任务协调器。 */
@Service
public class PersistentJobCoordinator {
 private final JobMapper mapper;
 private final LeaseExpiryDiagnostics leaseDiagnostics;
 @Autowired public PersistentJobCoordinator(JobMapper mapper, LeaseExpiryDiagnostics leaseDiagnostics){this.mapper=mapper;this.leaseDiagnostics=leaseDiagnostics;}
 /** 兼容不启动 Spring 容器的协调器单元测试。 */
 PersistentJobCoordinator(JobMapper mapper){this(mapper,null);}
 public JobEntity create(String type,String key,long actor){return create(type,key,actor,"{}");}
 public JobEntity create(String type,String key,long actor,String config){return create(type,key,actor,config,null);}
 /** 创建任务时固化目标卷，后续 ACTIVE 卷切换不得改变该字段。 */
 public JobEntity create(String type,String key,long actor,String config,Long targetStorageVolumeId){JobEntity j=new JobEntity();j.setJobNo(UUID.randomUUID().toString());j.setJobType(type);j.setStatus("CREATED");j.setIdempotencyKey(key);j.setPriority(0);j.setProgressCurrent(0L);j.setProgressTotal(0L);j.setConfigSnapshotJson(config==null?"{}":config);j.setTargetStorageVolumeId(targetStorageVolumeId);j.setRequestedBy(actor);j.setRequestedAt(LocalDateTime.now());j.setFencingToken(0L);j.setRetryCount(0);j.setCancelRequested(false);try{mapper.insert(j);return j;}catch(DuplicateKeyException duplicate){JobEntity existing=mapper.selectOne(Wrappers.<JobEntity>lambdaQuery().eq(JobEntity::getIdempotencyKey,key).last("limit 1"));if(existing!=null)return existing;throw duplicate;}}
 public JobEntity retry(long id,long actor){JobEntity old=required(id);if(!"FAILED".equals(old.getStatus())&&!"PARTIAL_FAILED".equals(old.getStatus())&&!"CANCELLED".equals(old.getStatus()))throw new IllegalStateException("只能重试失败、部分失败或已取消任务");String key="retry-of:"+old.getId()+":"+UUID.randomUUID();return create(old.getJobType(),key,actor,old.getConfigSnapshotJson(),old.getTargetStorageVolumeId());}
 public JobEntity claimNext(String owner,long lease){LocalDateTime now=LocalDateTime.now();List<JobEntity> list=mapper.selectList(Wrappers.<JobEntity>lambdaQuery().eq(JobEntity::getStatus,"CREATED").and(w->w.isNull(JobEntity::getNextRetryAt).or().le(JobEntity::getNextRetryAt,now)).orderByDesc(JobEntity::getPriority).orderByAsc(JobEntity::getId).last("limit 10"));for(JobEntity j:list){try{return claim(j.getId(),owner,lease);}catch(IllegalStateException ignored){}}return null;}
 public JobEntity claim(long id,String owner,long lease){if(owner==null||owner.isBlank()||lease<=0)throw new IllegalArgumentException("租约参数非法");JobEntity j=required(id);LocalDateTime now=LocalDateTime.now();boolean available="CREATED".equals(j.getStatus())||("RUNNING".equals(j.getStatus())&&j.getLeaseUntil()!=null&&!j.getLeaseUntil().isAfter(now));if(!available)throw new IllegalStateException("任务不可领取");int rows=mapper.update(null,Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,id).eq(JobEntity::getVersion,j.getVersion()).eq(JobEntity::getStatus,j.getStatus()).set(JobEntity::getStatus,"RUNNING").set(JobEntity::getLeaseOwner,owner).set(JobEntity::getLeaseUntil,now.plusSeconds(lease)).set(JobEntity::getHeartbeatAt,now).set(JobEntity::getFencingToken,value(j.getFencingToken())+1).set(JobEntity::getStartedAt,j.getStartedAt()==null?now:j.getStartedAt()));if(rows!=1)throw new IllegalStateException("任务已被其他执行器领取");return required(id);}
 public void heartbeat(long id,String owner,long token,long lease){JobEntity j=required(id);validate(j,owner,token);cancelIfRequested(j,owner,token);LocalDateTime now=LocalDateTime.now();requireUpdated(apply(guarded(id,owner,token).gt(JobEntity::getLeaseUntil,now).set(JobEntity::getLeaseUntil,now.plusSeconds(lease)).set(JobEntity::getHeartbeatAt,now)));}
 /** 仅供后台心跳续租，不在心跳线程内推进取消状态；取消仍由业务安全点处理。 */
 public void renewLease(long id,String owner,long token,long lease){JobEntity j=required(id);validate(j,owner,token);LocalDateTime now=LocalDateTime.now();requireUpdated(apply(guarded(id,owner,token).gt(JobEntity::getLeaseUntil,now).set(JobEntity::getLeaseUntil,now.plusSeconds(lease)).set(JobEntity::getHeartbeatAt,now)));}
 public void safePoint(long id,String owner,long token,String step,long progress){JobEntity j=required(id);validate(j,owner,token);cancelIfRequested(j,owner,token);requireUpdated(apply(guarded(id,owner,token).set(JobEntity::getCurrentStep,step).set(JobEntity::getProgressCurrent,Math.max(progress,0)).set(JobEntity::getHeartbeatAt,LocalDateTime.now())));}
 /** 在任务仍持有有效租约时切换运行阶段；用于向管理端展示失败订单集中重试阶段。 */
 public void activeStatus(long id,String owner,long token,String status,String step,long progress){if(!"RUNNING".equals(status)&&!"RETRYING_FAILED_ORDERS".equals(status))throw new IllegalArgumentException("非法运行态");JobEntity j=required(id);validate(j,owner,token);cancelIfRequested(j,owner,token);requireUpdated(apply(guarded(id,owner,token).set(JobEntity::getStatus,status).set(JobEntity::getCurrentStep,step).set(JobEntity::getProgressCurrent,Math.max(progress,0)).set(JobEntity::getHeartbeatAt,LocalDateTime.now())));}
 public void succeed(long id,String owner,long token){requireUpdated(apply(guarded(id,owner,token).eq(JobEntity::getCancelRequested,false).set(JobEntity::getStatus,"SUCCEEDED").set(JobEntity::getFinishedAt,LocalDateTime.now()).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null)));}
 public void partial(long id,String owner,long token,String message){String safe=message==null?"部分任务项失败":message.substring(0,Math.min(1000,message.length()));requireUpdated(apply(guarded(id,owner,token).set(JobEntity::getStatus,"PARTIAL_FAILED").set(JobEntity::getFailureCode,"PARTIAL_FAILED").set(JobEntity::getFailureMessage,safe).set(JobEntity::getFinishedAt,LocalDateTime.now()).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null)));}
 public void storeResult(long id,String owner,long token,String resultJson){requireUpdated(apply(guarded(id,owner,token).set(JobEntity::getResultJson,resultJson)));}
 public void failOrRetry(long id,String owner,long token,int maxRetries,Throwable failure){JobEntity j=required(id);validate(j,owner,token);int retry=(j.getRetryCount()==null?0:j.getRetryCount())+1;boolean again=retry<=maxRetries&&!Boolean.TRUE.equals(j.getCancelRequested());String message=failure==null||failure.getMessage()==null?"任务执行失败":failure.getMessage();if(message.length()>1000)message=message.substring(0,1000);var u=guarded(id,owner,token).set(JobEntity::getRetryCount,retry).set(JobEntity::getFailureCode,failure==null?"JOB_FAILED":failure.getClass().getSimpleName()).set(JobEntity::getFailureMessage,message).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null);if(again){long delay=Math.min(300L,1L<<Math.min(retry-1,8));u.set(JobEntity::getStatus,"CREATED").set(JobEntity::getNextRetryAt,LocalDateTime.now().plusSeconds(delay));}else{u.set(JobEntity::getStatus,Boolean.TRUE.equals(j.getCancelRequested())?"CANCELLED":"FAILED").set(JobEntity::getFinishedAt,LocalDateTime.now());}requireUpdated(apply(u));}
 public void requestCancel(long id){JobEntity job=required(id);int rows;if("CREATED".equals(job.getStatus())||"PAUSED".equals(job.getStatus())){rows=mapper.update(null,Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,id).eq(JobEntity::getStatus,job.getStatus()).set(JobEntity::getCancelRequested,true).set(JobEntity::getStatus,"CANCELLED").set(JobEntity::getFinishedAt,LocalDateTime.now()).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null));}else if(active(job.getStatus())){rows=mapper.update(null,Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,id).eq(JobEntity::getStatus,job.getStatus()).set(JobEntity::getCancelRequested,true));}else{throw new IllegalStateException("任务当前状态不可取消: "+job.getStatus());}if(rows!=1)throw new IllegalStateException("任务状态已变更，请刷新后重试");}
 public int recoverExpired(){return recoverExpired(3);}
 public int recoverExpired(int maxRetries){if(maxRetries<0)throw new IllegalArgumentException("最大重试次数不能小于0");LocalDateTime now=LocalDateTime.now();List<JobEntity> list=mapper.selectList(Wrappers.<JobEntity>lambdaQuery().in(JobEntity::getStatus,"RUNNING","RETRYING_FAILED_ORDERS").isNotNull(JobEntity::getLeaseUntil).le(JobEntity::getLeaseUntil,now));int count=0;for(JobEntity j:list){int retry=(j.getRetryCount()==null?0:j.getRetryCount())+1;boolean terminal=retry>maxRetries;String detail=leaseDiagnostics==null?"执行器租约过期":leaseDiagnostics.describe(j);var update=Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,j.getId()).eq(JobEntity::getVersion,j.getVersion()).eq(JobEntity::getStatus,j.getStatus()).le(JobEntity::getLeaseUntil,now).set(JobEntity::getStatus,terminal?"FAILED":"CREATED").set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null).set(JobEntity::getNextRetryAt,terminal?null:now).set(JobEntity::getRetryCount,retry).set(JobEntity::getFailureCode,"LEASE_EXPIRED").set(JobEntity::getFailureMessage,terminal?detail+"，已达到最大恢复次数":detail+"，等待恢复");if(terminal)update.set(JobEntity::getFinishedAt,now);int rows=mapper.update(null,update);if(rows==1)count++;}return count;}
 private com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<JobEntity> guarded(long id,String owner,long token){return Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,id).in(JobEntity::getStatus,"RUNNING","RETRYING_FAILED_ORDERS").eq(JobEntity::getLeaseOwner,owner).eq(JobEntity::getFencingToken,token);}
 private int apply(com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<JobEntity> update){return mapper.update(null,update);}
 private JobEntity required(long id){JobEntity j=mapper.selectById(id);if(j==null)throw new IllegalArgumentException("任务不存在");return j;}
 private static long value(Long n){return n==null?0:n;} private static void requireUpdated(int n){if(n!=1)throw new IllegalStateException("租约或 fencing token 无效");}
 private static void validate(JobEntity j,String owner,long token){if(!active(j.getStatus())||!owner.equals(j.getLeaseOwner())||value(j.getFencingToken())!=token)throw new IllegalStateException("租约或 fencing token 无效");}
 private static boolean active(String status){return "RUNNING".equals(status)||"RETRYING_FAILED_ORDERS".equals(status);}
 private void cancelIfRequested(JobEntity job,String owner,long token){if(!Boolean.TRUE.equals(job.getCancelRequested()))return;requireUpdated(apply(guarded(job.getId(),owner,token).set(JobEntity::getStatus,"CANCELLED").set(JobEntity::getFinishedAt,LocalDateTime.now()).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null)));throw new JobCancelledException("任务已在安全点取消");}
}
